import{_t as e,it as t,n,rt as r}from"./chunks/framework.BM2esBXZ.js";var i=JSON.parse(`{"title":"LLMs.txt","description":"","frontmatter":{},"headers":[],"relativePath":"agents/llms.md","filePath":"agents/llms.md","lastUpdated":1794052435000}`),a={name:`agents/llms.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="llms-txt" tabindex="-1">LLMs.txt <a class="header-anchor" href="#llms-txt" aria-label="Permalink to “LLMs.txt”">​</a></h1><p>文档站在构建时产出一组给大语言模型读取的纯文本资产，内容与站点正文同源。本页列出这些资产与在 AI 工具中的用法。</p><h2 id="可用资源" tabindex="-1">可用资源 <a class="header-anchor" href="#可用资源" aria-label="Permalink to “可用资源”">​</a></h2><p>下表的路径相对文档站根地址：</p><table tabindex="0"><thead><tr><th>文件</th><th>说明</th></tr></thead><tbody><tr><td><code>/llms.txt</code></td><td>索引：全部页面的标题、一句话摘要与地址，以及下列资产的入口</td></tr><tr><td><code>/llms-full.txt</code></td><td>全站正文</td></tr><tr><td><code>/llms-guide.txt</code></td><td>开发指南全部章节</td></tr><tr><td><code>/llms-packages.txt</code></td><td>包总览与全部包页</td></tr></tbody></table><p>单页 Markdown：任一页面地址后加 <code>.md</code> 得到这一页的 Markdown，例如 <code>/guide/operations.md</code>、<code>/packages/kernel.md</code>。每页正文上方的「取本页 Markdown」指向它。</p><p><code>llms-full.txt</code> 体积较大。多数场景先读 <code>llms.txt</code> 索引，再按需取单页或只取用到的分册。</p><h2 id="在-ai-工具中使用" tabindex="-1">在 AI 工具中使用 <a class="header-anchor" href="#在-ai-工具中使用" aria-label="Permalink to “在 AI 工具中使用”">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>做法</th></tr></thead><tbody><tr><td>Claude Code</td><td>写进项目的 <code>CLAUDE.md</code></td></tr><tr><td>Cursor</td><td>写进 <code>.cursor/rules</code>，或在对话里用 <code>@Docs</code> 添加 <code>llms.txt</code> 的地址</td></tr><tr><td>Codex</td><td>写进项目的 <code>AGENTS.md</code></td></tr><tr><td>GitHub Copilot</td><td>写进 <code>.github/copilot-instructions.md</code></td></tr><tr><td>Windsurf</td><td>写进 <code>.windsurf/rules</code></td></tr></tbody></table><p>可以直接使用的提示词见 <a href="./agents">For Agents</a>。在 XiHan.Framework 仓库内工作的工具可以不经网络，直接读 <code>docs/</code> 下的 Markdown 源文件。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to “相关”">​</a></h2><ul><li><a href="./agents">For Agents</a> · <a href="./mcp">MCP Server</a> · <a href="./cli">CLI</a></li></ul>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};